CREATE TABLE IF NOT EXISTS report_exports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,report_type VARCHAR(80) NOT NULL,filters JSON NULL,format VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_report_exports_type(report_type,created_at));
